import{_ as t,o as e,c as o,ag as l}from"./chunks/framework.CAXxHpAX.js";const s=JSON.parse('{"title":"顽空","description":"","frontmatter":{},"headers":[],"relativePath":"50-概念资料/dict-顽空.md","filePath":"50-概念资料/dict-顽空.md","lastUpdated":1778033203000}'),i={name:"50-概念资料/dict-顽空.md"};function r(u,a,h,d,n,c){return e(),o("div",null,[...a[0]||(a[0]=[l('<h1 id="顽空" tabindex="-1">顽空 <a class="header-anchor" href="#顽空" aria-label="Permalink to &quot;顽空&quot;">​</a></h1><h2 id="定义" tabindex="-1">定义 <a class="header-anchor" href="#定义" aria-label="Permalink to &quot;定义&quot;">​</a></h2><p>顽空是修行误区：把&quot;空&quot;误解为什么都没有、什么都不做、什么都不想，陷入死寂和消极的状态。</p><h2 id="了空居士原话" tabindex="-1">了空居士原话 <a class="header-anchor" href="#了空居士原话" aria-label="Permalink to &quot;了空居士原话&quot;">​</a></h2><blockquote><p>&quot;最清净的人就是死人。第二清净的人就是老人痴呆症。&quot;</p></blockquote><blockquote><p>&quot;有些人以为打坐就是要&#39;入静&#39;，拼命压念头，越压越烦躁。&quot;</p></blockquote><blockquote><p>&quot;万法皆空，因果不空——万事万物都不是永恒的，但是因果相续的规律是永恒的。&quot;</p></blockquote><h2 id="顽空的表现" tabindex="-1">顽空的表现 <a class="header-anchor" href="#顽空的表现" aria-label="Permalink to &quot;顽空的表现&quot;">​</a></h2><ul><li>以为修行就是&quot;什么都不想&quot; → 变成发呆</li><li>以为&quot;空&quot;就是没有感觉 → 变成麻木</li><li>以为&quot;放下&quot;就是什么都不管 → 变成不负责任</li><li>以为&quot;无我&quot;就是没有自我 → 变成自卑</li></ul><h2 id="如何避免" tabindex="-1">如何避免 <a class="header-anchor" href="#如何避免" aria-label="Permalink to &quot;如何避免&quot;">​</a></h2><p>了空居士说：<strong>空不是没有，是不永恒。</strong> 照见五蕴皆空，是知道一切都在变化，不是否定一切存在。</p><h2 id="相关概念" tabindex="-1">相关概念 <a class="header-anchor" href="#相关概念" aria-label="Permalink to &quot;相关概念&quot;">​</a></h2><ul><li><a href="/50-概念资料/dict-清净心">清净心</a> — 清净心不是顽空</li><li><a href="/50-概念资料/dict-观照">观照</a> — 以观照破顽空</li></ul><h2 id="相关模型" tabindex="-1">相关模型 <a class="header-anchor" href="#相关模型" aria-label="Permalink to &quot;相关模型&quot;">​</a></h2><ul><li><a href="/10-核心模型/model-自然务实">自然务实</a> — 不落入顽空的实践态度</li></ul><h2 id="修行实践" tabindex="-1">修行实践 <a class="header-anchor" href="#修行实践" aria-label="Permalink to &quot;修行实践&quot;">​</a></h2><ul><li>静坐时观照而不压抑念头</li><li>生活中积极做事但不执着结果</li></ul>',17)])])}const _=t(i,[["render",r]]);export{s as __pageData,_ as default};
